[CmdletBinding()]
param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot),[string]$AccountKey,[Alias('Home')][string]$HomePath,[string]$State,[string]$UserData,[string]$ExpectedEmail)
$ErrorActionPreference='Stop'
$config=Join-Path $ProjectRoot 'config\accounts.json'
$log=Join-Path $ProjectRoot 'logs\manager.log'
$mutex=[Threading.Mutex]::new($false,'Local\CodexAccountManager.RegistryWrite')
if(-not$mutex.WaitOne(0)){throw 'Another account login is already running'}
function Write-Log([string]$m){Add-Content -LiteralPath $log -Value ((Get-Date).ToString('o')+' [ADD] '+$m) -Encoding UTF8}
function Next-Key([object[]]$items){$used=@();foreach($item in $items){$v=[string]$item.Key;if($v.Length -eq 1){$used+=[int][char]$v}};foreach($n in 65..90){if($used -notcontains $n){return [char]$n}};throw 'No free account key'}
function Send-Rpc($p,[string]$json){$p.StandardInput.WriteLine($json);$p.StandardInput.Flush()}
function Read-Registry([string]$path){$raw=Get-Content -LiteralPath $path -Raw|ConvertFrom-Json;$value=$raw.PSObject.Properties['value'];if($null -ne $value -and $null -ne $value.Value){return @($value.Value)};return @($raw)}
function Full([string]$path){[IO.Path]::GetFullPath($path).TrimEnd('\')}
function Overlap([string]$a,[string]$b){$x=(Full $a)+'\';$y=(Full $b)+'\';return $x.StartsWith($y,[StringComparison]::OrdinalIgnoreCase) -or $y.StartsWith($x,[StringComparison]::OrdinalIgnoreCase)}
function Assert-CoreAccounts([object[]]$records){$required=@('A','B','C','D','E');foreach($id in $required){$matches=@($records|Where-Object {[string]$_.Key -eq $id});if($matches.Count -ne 1){throw "Registry integrity failure: expected exactly one account $id, found $($matches.Count)"}};$nonEmpty=@($records|Where-Object {-not [string]::IsNullOrWhiteSpace([string]$_.Email)});$duplicateEmails=@($nonEmpty|Group-Object {[string]$_.Email}|Where-Object Count -gt 1);if($duplicateEmails.Count -gt 0){throw "Registry integrity failure: duplicate existing email(s): $($duplicateEmails.Name -join ', ')"}}
function CoreSnapshot([object[]]$records){@($records|Where-Object {[string]$_.Key -in @('A','B','C','D','E')}|Sort-Object Key|ConvertTo-Json -Depth 8 -Compress)}
function Assert-FinalRegistry([object[]]$records,[object]$saved,[string]$coreBefore){Assert-CoreAccounts $records;$f=@($records|Where-Object {[string]$_.Key -eq 'F'});if($f.Count -ne 1){throw "Registry integrity failure: expected exactly one account F, found $($f.Count)"};if((CoreSnapshot $records) -ne $coreBefore){throw 'Registry integrity failure: A-E changed during F registration'};foreach($field in @('Email','Home','State','UserData')){if([string]$f[0].$field -ne [string]$saved.$field){throw "Registry integrity failure: F $field mismatch after save"}}}
try{$items=@(Read-Registry $config)}catch{throw "Cannot read accounts registry: $($_.Exception.Message)"}
$initialRegistryHash=(Get-FileHash -LiteralPath $config -Algorithm SHA256).Hash
$required=@('Key','Home','State','UserData');foreach($item in $items){foreach($field in $required){if(-not $item.PSObject.Properties[$field]){throw "Registry schema mismatch: missing field $field"}}}
Assert-CoreAccounts $items
$coreBefore=CoreSnapshot $items
$key=if([string]::IsNullOrWhiteSpace($AccountKey)){[string](Next-Key $items)}else{$AccountKey.Trim().ToUpperInvariant()};if($key -notmatch '^[A-Z]$'){throw "AccountKey must be one letter A-Z: $key"}
$existing=@($items|Where-Object {[string]$_.Key -eq $key});if($existing.Count -gt 0){throw "Account key already exists: $key"}
$newHome=if([string]::IsNullOrWhiteSpace($HomePath)){Join-Path $env:USERPROFILE ('.codex-account-'+$key.ToLower())}else{Full $HomePath};$state=if([string]::IsNullOrWhiteSpace($State)){Join-Path $env:LOCALAPPDATA ('CodexAccountManager\QuotaState\'+$key)}else{Full $State};$userData=if([string]::IsNullOrWhiteSpace($UserData)){Join-Path $env:LOCALAPPDATA ('CodexAccountManager\'+$key+'\UserData')}else{Full $UserData}
if((Overlap $newHome $state) -or (Overlap $newHome $userData) -or (Overlap $state $userData)){throw 'Target paths overlap or contain one another'}
if(@($items|Where-Object { (Overlap $newHome ([string]$_.Home)) -or (Overlap $state ([string]$_.State)) -or (Overlap $userData ([string]$_.UserData)) }).Count -gt 0){throw "Account path collision for $key"}
foreach($target in @($newHome,$state,$userData)){if(Test-Path -LiteralPath $target){throw "Target path already exists: $target"}}
New-Item -ItemType Directory -Force $newHome,$state,$userData|Out-Null
$exe=Get-ChildItem (Join-Path $env:USERPROFILE '.codex\packages\app-server-daemon\releases') -Filter codex.exe -Recurse -File|Select-Object -First 1 -ExpandProperty FullName
if(-not$exe){throw 'Codex app-server executable not found'}
$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$exe;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardInput=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$si.Environment['CODEX_HOME']=$newHome
if($si.ArgumentList){foreach($x in @('app-server','--listen','stdio://','-c',('sqlite_home="'+$state+'"'))){[void]$si.ArgumentList.Add($x)}}else{$si.Arguments='app-server --listen stdio:// -c sqlite_home="'+$state+'"'}
$p=[Diagnostics.Process]::new();$p.StartInfo=$si;[void]$p.Start();$errTask=$p.StandardError.ReadToEndAsync();$deadline=(Get-Date).AddMinutes(10);$id=0;$loginId=$null;$account=$null
try {
 Send-Rpc $p '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"clientInfo":{"name":"codex-account-manager","title":"Codex Account Manager","version":"0.4.0"}}}'
 Send-Rpc $p '{"jsonrpc":"2.0","method":"initialized","params":{}}'
 Send-Rpc $p '{"jsonrpc":"2.0","id":2,"method":"account/login/start","params":{"type":"chatgpt","useHostedLoginSuccessPage":true,"appBrand":"chatgpt"}}'
 $read=$p.StandardOutput.ReadLineAsync();while((Get-Date)-lt$deadline){if($read.Wait(250)){$line=$read.Result;$read=$p.StandardOutput.ReadLineAsync();if([string]::IsNullOrEmpty($line)){throw 'App Server returned an empty response during login'};try{$j=$line|ConvertFrom-Json}catch{throw 'Invalid JSON from App Server during login'};if($j.error){throw 'JSON-RPC error during login'};if($j.id -eq 2){$loginId=[string]$j.result.loginId;$url=[string]$j.result.authUrl;if(-not$url){throw 'Login response did not contain authUrl'};Start-Process $url;Write-Log "account=$key login browser opened"}elseif($j.method -eq 'account/login/completed' -and ([string]$j.params.loginId -eq $loginId)) {if(-not$j.params.success){throw "Login failed: $($j.params.error)"};break}};if($p.HasExited){throw 'App Server exited during login'}}
 if(-not$loginId){throw 'No loginId received'}
 Send-Rpc $p '{"jsonrpc":"2.0","id":3,"method":"account/read","params":{}}'
 $read=$p.StandardOutput.ReadLineAsync();while((Get-Date)-lt$deadline){if($read.Wait(250)){$line=$read.Result;$read=$p.StandardOutput.ReadLineAsync();if([string]::IsNullOrEmpty($line)){throw 'App Server returned an empty response during account/read'};try{$j=$line|ConvertFrom-Json}catch{throw 'Invalid JSON from App Server during account/read'};if($j.error){throw 'JSON-RPC error during account/read'};if($j.id -eq 3){$account=$j.result.account;break}};if($p.HasExited){throw 'App Server exited before account/read'}}
 if(-not$account.email){throw 'Login completed but account/read returned no email'}
 if($ExpectedEmail -and ([string]$account.email).Trim().ToLowerInvariant() -ne $ExpectedEmail.Trim().ToLowerInvariant()){throw "Authenticated email does not match expected email"}
 $saved=[pscustomobject]@{Key=$key;Email=[string]$account.email;Plan=[string]$account.planType;Home=$newHome;State=$state;UserData=$userData;CreatedAt=(Get-Date).ToString('o');Status='verified'}
 $currentRaw=Get-Content -LiteralPath $config -Raw;$currentHash=(Get-FileHash -LiteralPath $config -Algorithm SHA256).Hash;if($currentHash -ne $initialRegistryHash){throw "Registry changed during OAuth; refusing to save (initial=$initialRegistryHash current=$currentHash)"};$current=@(Read-Registry $config);foreach($item in $current){foreach($field in $required){if(-not $item.PSObject.Properties[$field]){throw "Registry schema mismatch before save: missing field $field"}}};Assert-CoreAccounts $current;if((CoreSnapshot $current) -ne $coreBefore){throw 'Registry changed unexpectedly during OAuth; refusing to save'};if(@($current|Where-Object {[string]$_.Key -eq $key -or (Overlap $newHome ([string]$_.Home)) -or (Overlap $state ([string]$_.State)) -or (Overlap $userData ([string]$_.UserData))}).Count -gt 0){throw "Account key or path was taken during login"};$items=@($current)+$saved;$tmp=$config+'.tmp-'+[guid]::NewGuid().ToString('N');$rollback=$config+'.rollback-'+[guid]::NewGuid().ToString('N');$replaced=$false;try{$currentRaw|Set-Content -LiteralPath $rollback -Encoding UTF8;$candidate=$items|ConvertTo-Json -Depth 5;$candidate|ConvertFrom-Json|Out-Null;$candidateRecords=@($items);Assert-FinalRegistry $candidateRecords $saved $coreBefore;$candidate|Set-Content -LiteralPath $tmp -Encoding UTF8;Move-Item -LiteralPath $tmp -Destination $config -Force;$replaced=$true;$after=@(Read-Registry $config);Assert-FinalRegistry $after $saved $coreBefore;$newHash=(Get-FileHash -LiteralPath $config -Algorithm SHA256).Hash;Write-Log "account=$key source=CLI oldHash=$initialRegistryHash newHash=$newHash result=success"}catch{if(Test-Path -LiteralPath $tmp){Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue};if($replaced){try{Move-Item -LiteralPath $rollback -Destination $config -Force;$restored=@(Read-Registry $config);Assert-CoreAccounts $restored;if((CoreSnapshot $restored) -ne $coreBefore){throw 'Rollback content mismatch'};Write-Log "account=$key registry rollback succeeded after verification failure"}catch{throw "Registry write verification failed and rollback failed: $($_.Exception.Message)"}};throw}finally{if(Test-Path -LiteralPath $tmp){Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue};if(Test-Path -LiteralPath $rollback){Remove-Item -LiteralPath $rollback -Force -ErrorAction SilentlyContinue}}
 Write-Log "account=$key login verified email=$($account.email)";Write-Output ($saved|ConvertTo-Json -Depth 5)
} finally {if($p -and -not$p.HasExited){$p.Kill()};if($p){$p.Dispose()};$mutex.ReleaseMutex();$mutex.Dispose()}
